const moment=require("moment"),Avatar=require("../models/avatarsModel"),handleErrors=require("../utilities/handle_errors")["handleErrors"],create_avatar=(t,e,a)=>{Avatar.create(t.body).then(a=>{e.status(200).send(a)}).catch(a=>{e.status(422).send(handleErrors(a,t,"avatar"))})},get_avatars=(a,e,r)=>{const n=a.query.page-1||0,d=moment(new Date).format("YYYY-MM-DD");Avatar.find({$or:[{endDate:{$gte:d}},{endDate:{$in:["",null]}}]}).count().then(t=>{Avatar.find({$or:[{endDate:{$gte:d}},{endDate:{$in:["",null]}}]}).sort({createdAt:-1}).skip(8*n).limit(8).lean().then(a=>e.status(200).send({avatars:a,total_avatars:t,per_page:8})).catch(r)})},get_admin_avatars=(a,e,r)=>{const n=a.query.page-1||0;Avatar.find({}).count().then(t=>{Avatar.find({}).skip(30*n).limit(30).then(a=>e.status(200).send({avatars:a,total_avatars:t,per_page:30})).catch(r)})},get_single_avatar=(a,t,e)=>{Avatar.findById({_id:a.params.id}).then(a=>t.status(200).send(a)).catch(e)},update_avatar=(t,e,a)=>{Avatar.findByIdAndUpdate({_id:t.params.id},t.body).then(a=>{Avatar.findOne({_id:t.params.id}).then(a=>e.status(200).send(a))}).catch(a)},delete_avatar=(a,t,e)=>{Avatar.findByIdAndDelete({_id:a.params.id}).then(a=>{t.status(200).send(a)}).catch(e)};module.exports={create_avatar:create_avatar,update_avatar:update_avatar,get_single_avatar:get_single_avatar,get_admin_avatars:get_admin_avatars,get_avatars:get_avatars,delete_avatar:delete_avatar};